Clinician Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Clinician Portal container

Container_Boundary(clinician_portal, "Clinician Portal") {
    Component(clinician_ui, "Clinician UI", "React / TypeScript", "Low-latency user interface for licensed clinicians to manage consultations and prescriptions.")
    Component(clinician_backend, "Clinician Backend Layer", "Node.js / Express", "Backend component layer handling session management and prescription routing.")
}

Rel(clinician_ui, clinician_backend, "Communicates via HTTPS/REST for session and prescription operations.", "HTTPS/REST")

@enduml

GCP API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the GCP API Gateway container

Container_Boundary(gcp_api_gateway, "GCP API Gateway") {
    Component(Cloud_Endpoints_Envoy_Router, "Cloud Endpoints Envoy Router", "Cloud Endpoints / Envoy", "Handles edge routing, Anycast geo-routing, and local JWT validation to minimize latency and enforce physical entry-point segregation.")
    Component(Authentication_and_Authorization_Handler, "Authentication and Authorization Handler", "OIDC, HTTPS, OAuth2/JWT", "Authenticates users via Regional Identity Providers and validates security tokens.")
    Component(Audit_Endpoint_Handler, "Audit Endpoint Handler", "mTLS, signed JWTs, HTTPS", "Manages secure access for Regional Health Authorities and Auditors to audit endpoints.")
}

Rel(Cloud_Endpoints_Envoy_Router, Authentication_and_Authorization_Handler, "Validates incoming tokens and authenticates users", "OIDC, HTTPS")
Rel(Cloud_Endpoints_Envoy_Router, Audit_Endpoint_Handler, "Enforces mTLS and signed JWT checks for compliance", "mTLS, HTTPS")

@enduml

AI Inference Wrapper.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AI Inference Wrapper container

Container_Boundary(ai_inference_wrapper, "AI Inference Wrapper") {
    Component(AI_Inference_API_Router, "AI Inference API Router", "Python / FastAPI", "Handles incoming gRPC requests from the Core Telehealth Service and routes them to the symptom checker models.")
    Component(Model_Execution_Engine, "Model Execution Engine", "Python", "Executes symptom checking AI models and formats the clinical output.")
    Component(Audit_Log_Publisher, "Audit Log Publisher", "Python gRPC Client", "Publishes asynchronous audit logs and traceability data to GCP Cloud Pub/Sub for EU MDR compliance.")
}

Rel(AI_Inference_API_Router, Model_Execution_Engine, "Invokes symptom analysis", "gRPC")
Rel(AI_Inference_API_Router, Audit_Log_Publisher, "Sends audit events asynchronously", "Internal Call")
@enduml

GCP GKE Regional Clusters.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(gcp_gke_regional_clusters, "GCP GKE Regional Clusters") {
    Component(ingress_controllers, "Kubernetes Ingress Controllers (NGINX / Envoy)", "NGINX / Envoy", "Manages TLS termination and ingress traffic routing for regional clusters.")
    Component(network_policy_enforcer, "Network Policy Enforcer (GKE Dataplane V2 / eBPF)", "GKE Dataplane V2 / eBPF", "Enforces pod isolation and namespace segmentation using Layer 3/4 eBPF protocols.")
    Component(log_forwarder, "Log Forwarder & OTel Collectors", "Fluentbit / OpenTelemetry", "Streams audit logs and telemetry data to observability platforms.")
    Component(core_services, "Core Telehealth & AI Inference Services", "Microservices (Containerized)", "Handles video streaming, prescriptions, and AI symptom analysis.")
}

Rel(ingress_controllers, core_services, "Routes HTTPS/gRPC application traffic to internal microservices.", "HTTPS/gRPC")
Rel(network_policy_enforcer, core_services, "Enforces workload isolation and security boundaries.", "Layer 3/4 eBPF")
Rel(log_forwarder, core_services, "Collects logs and telemetry data from microservices.", "gRPC/HTTPS")

@enduml

GCP Cloud Pub/Sub.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(gcp_cloud_pub_sub, "GCP Cloud Pub/Sub") {
    Component(Regional_Topics, "Regional Topics", "GCP Cloud Pub/Sub", "Region-isolated messaging topics ensuring regional data residency for e-prescriptions and audit logs.")
    Component(Dead_Letter_Topics, "Dead Letter Topics", "GCP Cloud Pub/Sub", "Captures undeliverable messages to ensure e-prescription reliability for unstable connections.")
    Component(Schema_Validator, "Schema Validator", "Avro / Protocol Buffers", "Enforces data contracts at the Pub/Sub ingestion boundary.")
}

Rel(Regional_Topics, Dead_Letter_Topics, "Routes undeliverable messages", "")
Rel(Schema_Validator, Regional_Topics, "Validates message payloads before ingestion", "")

@enduml
